mapper.select:
select a.id, a.user_id, u.username, a.appeal_time, a.appeal_reason, a.status, a.reviewer_id, auditor.name as reviewerName, a.review_time, a.review_result, a.review_reason, a.email from appeal a left join user u on a.user_id = u.id left join auditor on a.reviewer_id = auditor.id
and a.status = #{status}
and a.user_id = #{userId}
and a.reviewer_id = #{reviewerId}
order by a.appeal_time desc
